"""Página inicial — OTHIL Relatórios Comerciais."""
import datetime
import streamlit as st

_LOGO_B64 = ""

hoje      = datetime.date.today()
dias_pt   = ["Segunda-feira","Terça-feira","Quarta-feira","Quinta-feira",
             "Sexta-feira","Sábado","Domingo"]
meses_pt  = ["janeiro","fevereiro","março","abril","maio","junho",
             "julho","agosto","setembro","outubro","novembro","dezembro"]
data_fmt  = f"{dias_pt[hoje.weekday()]}, {hoje.day} de {meses_pt[hoje.month-1]} de {hoje.year}"

st.markdown(f"""
<div style="height:1.5rem;"></div>
<div style="text-align:center; padding-bottom:0.8rem;">
    <img src="data:image/png;base64,{_LOGO_B64}"
         style="max-width:300px; width:55%; height:auto;" />
</div>
<div style="text-align:center; padding:0.4rem 0 0.4rem;">
    <div style="color:#1B4332; font-size:1.05rem; font-weight:600;
                letter-spacing:0.04em; margin-bottom:0.6rem;">
        Relatórios Comerciais
    </div>
    <div style="display:inline-block; background:#2D6A4F; color:#c8ebd6;
                padding:0.3rem 1.3rem; border-radius:20px;
                font-size:0.82rem; font-weight:500;">
        {data_fmt}
    </div>
</div>
<div style="margin: 1.4rem auto; width:60px; height:3px;
            background:#2D6A4F; border-radius:2px;"></div>
<div style="text-align:center; color:#888; font-size:0.83rem;">
    Use o menu lateral para acessar os módulos
</div>
""", unsafe_allow_html=True)
